  const views = isNum2(t.views) ? compact(t.views) : "\u2014";
  const likes = isNum2(t.likes) ? compact(t.likes) : "\u2014";
  const third = t.rate !== undefined ? cell(percent(t.rate), "engagement") : cell(isNum2(t.comments) ? compact(t.comments) : "\u2014", t.comments === 1 ? "comment" : "comments");
